{
  "parties": [
    {
      "name": "上海安硕信息技术股份有限公司",
      "penalty_amount": 600000,
      "penalty_type": "警告并罚款",
      "position": "公司",
      "quote": "一、对安硕信息给予警告，并处以 60 万元罚款；"
    },
    {
      "name": "高鸣",
      "penalty_amount": 300000,
      "penalty_type": "警告并罚款",
      "position": "时任安硕信息董事长",
      "quote": "二、对高鸣给予警告，并处以 30 万元罚款；"
    },
    {
      "name": "曹丰",
      "penalty_amount": 200000,
      "penalty_type": "警告并罚款",
      "position": "时任安硕信息董事会秘书",
      "quote": "三、对曹丰给予警告，并处以 20 万元罚款。"
    }
  ],
  "doc_number": "[2016]138号",
  "dates": {
    "investigation_notice": "2015年8月14日",
    "prior_notice": "2016年6月14日",
    "decision_date": "2016年12月20日",
    "announcement_date": "2016年12月20日"
  },
  "fraud_facts": [
    {
      "item": "互联网金融服务业务收入",
      "amount": 1371900,
      "quote": "2014 年年报中互联网金融服务业务收入仅为 137.19 万元，占主营业务收入的 0.62%。"
    },
    {
      "item": "征信业务投入",
      "amount": 500000,
      "quote": "一是征信业务公司成立一年时间没有任何进展，仅投入了 50 万元和 3 名工作人员。"
    },
    {
      "item": "小贷云业务投入",
      "amount": 7170000,
      "quote": "三是小贷云业务虽然有 717 万元投入，但小贷云业务的实质为在其软件开发基础上的延伸服务。"
    },
    {
      "item": "拟累积投资总额",
      "amount": 90100000,
      "quote": "拟累积投资总额达 9,010 万元。"
    }
  ],
  "delisting_risk": null,
  "quotes": [
    "上海安硕信息技术股份有限公司（以下简称“公司”或“安硕信息”）于 2015 年 8 月 14 日收到中国证券监督管理委员会（以下简称“中国证监会”）《调查通知书》（沪证专调查字 2015282 号）。",
    "2016 年 6 月 14 日公司收到中国证监会下发的《行政处罚事先告知书》（编号：处罚字[2016]53 号）并予以披露。",
    "2016 年 12 月 20 日公司收到了中国证监会下发的 [2016]138 号《行政处罚决定书》。",
    "安硕信息的行为违反了《证券法》第六十三条规定，构成《证券法》一百九十三条第一款所述的违法行为，高鸣、曹丰是直接负责的主管人员。",
    "根据当事人违法行为的事实、性质、情节与社会危害程度，依据《证券法》第一百九十三条的规定，中国证监会决定：一、对安硕信息给予警告，并处以 60 万元罚款；二、对高鸣给予警告，并处以 30 万元罚款；三、对曹丰给予警告，并处以 20 万元罚款。"
  ]
}

